import java.util.*;
import java.io.*;

public class Main {
    static int n;
    static char[][] grid;

    static String solve(int r, int c, int size) {
        char first = grid[r][c];
        boolean same = true;
        for (int i = r; i < r + size && same; i++)
            for (int j = c; j < c + size; j++)
                if (grid[i][j] != first) { same = false; break; }
        if (same) return String.valueOf(first);
        int half = size / 2;
        return "(" + solve(r, c, half) + solve(r, c + half, half)
                + solve(r + half, c, half) + solve(r + half, c + half, half) + ")";
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.whitespaceChars('9', '9');
        st.whitespaceChars('0', '0');
        st.parseNumbers();
        st.wordChars('0', '9');
        if (st.nextToken() == StreamTokenizer.TT_EOF) return;
        n = (int) st.nval;
        grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) line = br.readLine();
            if (line == null) line = "";
            grid[i] = line.trim().toCharArray();
        }
        System.out.println(solve(0, 0, n));
    }
}
```

